def solution(input_str):
    import re
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    events = []
    segment_id = 0
    current_segment = 0

    for line in lines[1:]:
        if line == '1':
            current_segment += 1
        else:
            friend_name = line.split()[1]
            events.append((current_segment, friend_name))

    # Group visits by segment
    seg_to_friends = {}  # segment -> set of friends in that segment

    for segment, friend in events:
        if segment not in seg_to_friends:
            seg_to_friends[segment] = set()
        seg_to_friends[segment].add(friend)

    # Also need to track each friend's minimum and maximum segment they visit
    friend_segments = set()  # all friends involved

    for segment, friends in seg_to_friends.items():
        for f in friends:
            friend_segments.add(f)

    # Conflict graph: edges between friends who appear in the same segment
    # Two friends conflict if they both visit some segment

    # Build adjacency
    adj = {f: set() for f in friend_segments}
    friend_list = sorted(friend_segments)
    n_friends = len(friend_list)
    friend_to_idx = {f: i for i, f in enumerate(friend_list)}

    for segment, friends in seg_to_friends.items():
        friends_list = list(friends)
        for i, f1 in enumerate(friends_list):
            for f2 in friends_list[i+1:]:
                adj[f1].add(f2)
                adj[f2].add(f1)

    # Maximum independent set using backtracking with bitmask
    best = 0

    def solve(idx, count, mask):
        nonlocal best
        if idx == n_friends:
            if count > best:
                best = count
            return

        # Pruning: even if we pick all remaining, can't beat best
        remaining = n_friends - idx
        if count + remaining <= best:
            return

        # Skip friend at idx
        solve(idx + 1, count, mask)

        # Try taking friend at idx if it doesn't conflict with already picked
        conflicts = 0
        for friend in adj[friend_list[idx]]:
            if friend_to_idx[friend] in mask:
                conflicts += 1
                break

        take_valid = True
        # Check all conflicts
        for neighbor in adj[friend_list[idx]]:
            if friend_to_idx[neighbor] in mask:
                take_valid = False
                break

        if take_valid:
            new_mask = mask | (1 << friend_to_idx[friend_list[idx]])
            solve(idx + 1, count + 1, new_mask)

    # Optimization: sort by degree (number of conflicts) descending
    sorted_friends = sorted(friend_list, key=lambda f: len(adj[f]), reverse=True)
    sorted_idx_to_id = {id: idx for idx, id in enumerate(sorted_friends)}

    # Rebuild adjacency for sorted
    sorted_adj = {f: {g for g in adj[f]} for f in sorted_friends}
    sorted_friend_to_idx = {f: idx for idx, f in enumerate(sorted_friends)}

    best_sorted = 0

    def solve_sorted(idx, count, mask):
        nonlocal best_sorted
        if idx == n_friends:
            if count > best_sorted:
                best_sorted = count
            return

        if count + (n_friends - idx) <= best_sorted:
            return

        # Don't take
        solve_sorted(idx + 1, count, mask)

        # Take if valid
        can_take = True
        for neighbor in sorted_adj[sorted_friends[idx]]:
            if sorted_friend_to_idx[neighbor] in mask:
                can_take = False
                break

        if can_take:
            new_mask = mask | (1 << sorted_friend_to_idx[sorted_friends[idx]])
            solve_sorted(idx + 1, count + 1, new_mask)

    solve_sorted(0, 0, 0)

    str_result = str(best_sorted)
    return str_result

