        edge_idx = i
        edges.append((u, v, w, edge_idx))
        adj[u].append((v, edge_idx))
        adj[v].append((u, edge_idx))

    def bfs(start, excluded):
        visited = [False] * (n + 1)
        visited[start] = True
        queue = [start]

        while queue:
            curr = queue.pop(0)
            if curr == t:
                return True
            for neighbor, edge_idx in adj[curr]:
                if edge_idx not in excluded and not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return visited[t]

    # Check initial connectivity
    if not bfs(s, set()):
        return "0\n0"

    # Check single edge removal
    min_cost_1 = 2 * 10**18
    best_single = None

    for i in range(m):
        u, v, w, idx = edges[i]
        if bfs(s, {idx}):
            # If removing edge i disconnects s-t, it's a valid single cut
            if w < min_cost_1:
                min_cost_1 = w
                best_single = (w, idx)

    if best_single is not None:
        if best_single[0] == 0:
            return "0\n1\n" + str(best_single[1])
        cost_str = str(best_single[0])
        idx_str = str(best_single[1])
        return f"{cost_str}\n1\n{idx_str}"

    # Check two edge removal
    min_cost_2 = 2 * 10**18
    best_pair = None

    for i in range(m):
        u1, v1, w1, idx1 = edges[i]
        excluded1 = {idx1}
        if bfs(s, excluded1):
            # After removing edge i, we need to try pairs including i
            for j in range(i + 1, m):
                u2, v2, w2, idx2 = edges[j]
                excluded = excluded1 | {idx2}
                if not bfs(s, excluded):
                    total_cost = w1 + w2
                    if total_cost < min_cost_2:
                        min_cost_2 = total_cost
                        best_pair = (idx1, idx2)

    if best_pair is not None:
        idx1, idx2 = best_pair
        idx1, idx2 = sorted([idx1, idx2])
        return f"{min_cost_2}\n2\n{idx1} {idx2}"

    return "-1"

