def is_geometric(arr):
    n = len(arr)
    if n < 2:
        return True  # Single element or empty is always a GP

    # Check if all elements are zero
    if all(x == 0 for x in arr):
        return True

    r = arr[1] / arr[0]

    for i in range(2, n):
        if arr[i] != arr[i-1] * r:
            return False

    return True

