    def lit_to_node(val):
        # val is from input: e.g., 1, -2, etc.
        # positive means x|val|, negative means -x|val|
        var = abs(val) - 1  # 0-indexed
        # Return node for "this literal is TRUE"
        # If val > 0: x_var is True → node 2*var+1
        # If val < 0: -x_var is True (i.e. x_var is False) → node 2*var
        if val > 0:
            return 2 * var + 1  # x_var = True
        else:
            return 2 * var  # x_var = False (because -x_var = True)

    for clause in clauses:
        nesled = [lit_to_node(l) for l in clause]
        for i in range(len(nesled)):
            # If this literal is FALSE (i.e., ¬li), then at least one other must be TRUE
            # So: ¬li → lj for all j ≠ i
            from_node = nesled[i] ^ 1  # negation
            for j in range(len(nesled)):
                if i != j:
                    graph[from_node].append(nesled[j])

    # Check satisfiability using SCC
    # If variable x and ¬x are in same SCC → unsatisfiable

