        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(num_nodes):
        if not visited[i]:
            dfs1(i)

    component = [-1] * num_nodes
    timer = 0

    def dfs2(u, cid):
        component[u] = cid
        for v in _rev_graph[u]:
            if component[v] == -1:
                dfs2(v, cid)

    for i in range(len(order) - 1, -1, -1):
        u = order[i]
