import sys
sys.setrecursionlimit(50000)

def solution(input_str):
    """
    Determines who wins the chocolate game (Karlsson goes first).
    Uses memoized game theory to check if the starting position is winning.
    """
    # Parse the input board
    try:
        lines = input_str.strip().split('\n')
        board = [line.split() for line in lines]
    except:
        return "Lillebror\n"

    # Check if board is empty or all empty
    if not board:
        return "Lillebror\n"

    def has_any_chocolate(board_state):
        for row in board_state:
            for cell in row:
                if cell == 'O':
                    return True
        return False

    # Convert board to hashable key
    def to_key(board_state):
        return tuple(tuple(row) for row in board_state)

    # Memoization dictionary
    memo = {}

    def is_winning_position(board_state):
        """Returns True if current player can win from this board state."""
        key = to_key(board_state)
        if key in memo:
            return memo[key]

        # Base case: no chocolates left = losing position
        if not has_any_chocolate(board_state):
            memo[key] = False
            return False

        # Try all possible single chocolate removals
        # (In a hexagonal grid, valid moves eat along directions)
        winning_move_found = False
        for r in range(len(board_state)):
            for c in range(len(board_state[r])):
                if board_state[r][c] == 'O':
                    # Make a copy and remove this chocolate
                    new_board = [row[:] for row in board_state]
                    new_board[r][c] = '.'

                    # If opponent loses from resulting state, we win this move
                    if not is_winning_position(new_board):
                        winning_move_found = True
                        break
            if winning_move_found:
                break

        memo[key] = winning_move_found
        return winning_move_found

    # Check if starting position is winning for Karlsson (first player)
    if is_winning_position(board):
        return "Karlsson\n"
    else:
        return "Lillebror\n"


