                finish = (r, c)
                break
        if finish:
            break

    if finish is None:
        return ""

    # BFS to find path from start (0, 0) to finish
    start = (0, 0)
    queue = deque([(start, [])])
    visited = {start}

    # Direction mappings: (row_change, col_change, button_press)
    # U: up (row-1), D: down (row+1), L: left (col-1), R: right (col+1)
    directions = [(-1, 0, 'U'), (1, 0, 'D'), (0, -1, 'L'), (0, 1, 'R')]

    while queue:
        (r, c), path = queue.popleft()

        if (r, c) == finish:
            return '\n'.join(path) + '\n'

        for dr, dc, move in directions:
            nr, nc = r + dr, c + dc

            # Check bounds
            if nr < 0 or nr >= n or nc < 0 or nc >= m:
                continue

            # Check not dangerous
