                continue
            for val in range(1, m + 1):
                if s + val <= max_sum:
                    new_dp[s + val] = (new_dp[s + val] + dp[s]) % MOD
        dp = new_dp

    # Sum up: for each gap sum S, there are (n - S) valid starting positions
    total = 0
    for S in range(len(dp)):
