def solution(s):
    n = int(s.split('\n')[0])
    h = list(map(int, s.split('\n')[1].split()))

    i = 0
    while h[i] < h[i+1]:
        i = (i + 1) % n

    h = h[i:] + h[:i]

    left = [0] * n
    right = [0] * n

    stack = []
    for j in range(n):
        while stack and h[stack[-1]] < h[j]:
            stack.pop()
        left[j] = stack[-1] if stack else -1
        stack.append(j)

    stack = []
    for j in range(n-1, -1, -1):
        while stack and h[stack[-1]] < h[j]:
            stack.pop()
        right[j] = stack[-1] if stack else n + 1
        stack.append(j)

    first_max = 0
    count = 0
    for j in range(1, n):
        if h[first_max] >= h[j]:
            count += min(j, n - j)
        else:
            count += min(j, n - j)

    count += 0
    return str(count)

