def solution(input_str):
    n, p, l, r = map(int, input_str.split())

    fact = [1] * (n + 1)
    inv = [1] * (n + 1)
    inv[0] = 1
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % p
        inv[i] = (inv[i - 1] * pow(i, p - 2, p)) % p

    def nCk(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv[k] * inv[n - k] % p

    ans = 0
    for a in range(n + 1):
        for b in range(a + 1):
            c = n - a - b
            if c < 0:
                continue
            rem = a - b
            if l > rem or rem > r:
                continue

            # Compute Catalan-like number
            # Catalan(a, b) = (a - b + 1) / (a + 1) * C(a + b, b)
            if a + 1 == 0:
                catalan = 0
            else:
                catalan = (a - b + 1) * pow(a + 1, p - 2, p) % p * nCk(a + b, b) % p

            c_val = nCk(n, c)
            term = catalan * c_val % p
            ans = (ans + term) % p

    return str(ans)

MOD = 10**9 + 7

class Parser:
    def __init__(self, s):
        self.s = s
        self.pos = 0
        self.n = len(s)

    def peek(self):
        return self.s[self.pos] if self.pos < self.n else None

    def consume(self):
        self.pos += 1

    def parse_number(self):
        start = self.pos
        while self.peek() and self.peek().isdigit():
            self.consume()
        return int(self.s[start:self.pos])

    def parse_term(self):
        l = self.parse_number()

        # Case: number-range (l-r)
        if self.peek() == '-':
            self.consume()
            r = self.parse_number()
            return self.compute_range(l, r)

        # Case: number(expression)
        elif self.peek() == '(':
            self.consume()
            expr = self.parse_expression()
            self.consume()  # consume ')'
            self.consume()  # consume ')'
            # Handle the repeat logic
            base_val, base_len = expr
            num_digits = len(str(l))
            shift = pow(10, base_len, MOD)
            result_val = (l * pow(10, base_len * (num_digits % MOD), MOD) * base_val + 0) % MOD
            return (0, base_len * num_digits % MOD)

        # Case: just a number
        else:
            return (l, len(str(l)))

    def parse_expression(self):
        left = self.parse_term()
        while self.peek() == '+':
            self.consume()
            right = self.parse_term()
            left = self.concatenate(left, right)
        return left

    def concatenate(self, a, b):
        va, la = a
        vb, lb = b
        if la == 0:
            return b
        if lb == 0:
            return a
        shift = pow(10, lb, MOD)
        return ((va * shift + vb) % MOD, la + lb)

    def compute_range(self, l, r):
        val, length = 0, 0

        for n in range(l, r + 1):
            num_len = len(str(n))
            # Shift current result by the number's digit count
            # Since we're concatenating n directly after the previous numbers
            # we multiply by 10^num_len
            shift = pow(10, num_len, MOD)
            val = (val * shift + n) % MOD
            length += num_len

        return (val, length)

def solution(s):
    parser = Parser(s)
    result = parser.parse_expression()
    result_val, _ = result
    return str(result_val % MOD)

